import{_ as l,l as i,o as e,c as n,v as r,p as s,x as t,d,i as A,S as m}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"VQGAN","description":"","frontmatter":{"title":"VQGAN","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vqgan.md","filePath":"llm/vqgan.md","lastUpdated":1789023840000}'),p={name:"llm/vqgan.md"};function h(E,a,c,V,_,Q){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="vqgan" tabindex="-1">VQGAN <a class="header-anchor" href="#vqgan" aria-label="Permalink to &quot;VQGAN&quot;">​</a></h1><div class="epigraph"><p>同样是向量量化，解码器加上感知损失与对抗训练，重构才从「能认出」变成「能当生成器的词表」。</p><footer>—— Esser, Rombach, Ommer, Taming Transformers / VQGAN</footer></div><p><a href="/llm/vq-vae">上一课</a>的像素损失把高频细节平均掉。Esser 等人把 VQ 接到 VGG 感知距离与 PatchGAN 判别器上，得到 VQGAN。缺口是 tokenizer 的感知质量。后课 FSQ / LFQ 默认：对抗训练能锐，但不稳定、且不是唯一的量化器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自回归图像 Transformer 的上限受 tokenizer 重构天花板约束：LM 即使完美预测下标，解码也回不到比 VQ 解码器更好的图。VQ-VAE 的 L2 重构倾向模糊。VQGAN 改目标：在量化约束下最大化感知真实。训练更脆：GAN 与码本、重构要平衡，崩了会出纹理伪影。</p><p>它仍是离散码，空间分辨率由下采样钉死，与 ViT 的 \\(P\\) 类似，只是目标换成生成。</p><p><span class="marginnote">VQGAN 论文的另一半是在码上训 Transformer。本课只钉 tokenizer；自回归图像生成在后一单元。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编码器/量化/解码器骨架同 VQ-VAE，损失加感知（特征空间距离）与对抗。码本大小与下采样是图像 token 数的来源，必须与下游 LLM 上下文一起选。验收：重构 FID、人看文字与边缘、死码率。不要用 ImageNet 分类准确率当 tokenizer 分。</p>',9)),(e(),s(m,null,{default:t(()=>[A(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20VQ%5B%22VQ%20%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20VQ%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A%20%20DEC%20--%3E%20PER%5B%22%E6%84%9F%E7%9F%A5%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20DEC%20--%3E%20GAN%5B%22%E5%AF%B9%E6%8A%97%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20VQ%20--%3E%20TOK%5B%22%E7%A6%BB%E6%95%A3%20token%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对抗项迫使解码器把码字里没存下的高频「编造」得像自然图像；感知项对准人眼敏感的特征。量化仍丢信息，编造不等于恢复真细节——OCR 与精确布局会失败。这解释了为何文档 VLM 后来常走连续视觉编码器而不是 VQGAN 码。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>GAN tokenizer 训练贵、种子敏感。下一课 FSQ / LFQ 用更简单的量化网格，减轻码本学习。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VQGAN 用感知与对抗把 VQ 重构拉到可生成的质量。</li><li>下游 LM 的视觉上限受 tokenizer 天花板约束。</li><li>锐度不等于保真文字与布局。</li><li>出处：Esser, Rombach, Ommer, VQGAN。</li></ul>',6))])}const N=l(p,[["render",h]]);export{u as __pageData,N as default};
